    iron_gardenwheelbarrow = { name = "Železni vrtni voziček", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtni voziček za vrtnarje." },
    bronze_gardenwheelbarrow = { name = "Bronast vrtni voziček", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtni voziček za vrtnarje." },
    silver_gardenwheelbarrow = { name = "Srebrn vrtni voziček", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtni voziček za vrtnarje." },
    gilded_gardenwheelbarrow = { name = "Pozlačen vrtni voziček", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtni voziček za vrtnarje." },
    jewel_set_gardenwheelbarrow = { name = "Draguljast vrtni voziček", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtni voziček za vrtnarje." },
    royal_sovereign_gardenwheelbarrow = { name = "Kraljevski suveren vrtni voziček", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtni voziček z biseri za krono." },
}
