    sovereign_gardenwheelbarrow_palace = { name = "Suverena gardenwheelbarrow palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenWheelbarrowMaker.ironStock=14; GardenWheelbarrowMaker.bronzeStock=12; GardenWheelbarrowMaker.woodStock=18; GardenWheelbarrowMaker.leatherStock=10; GardenWheelbarrowMaker.silverStock=8; GardenWheelbarrowMaker.goldStock=6; GardenWheelbarrowMaker.jewelStock=4; GardenWheelbarrowMaker.pearlStock=4
GardenWheelbarrowMaker.productStock = {}; GardenWheelbarrowMaker.buildings = {}; GardenWheelbarrowMaker.maker = nil; GardenWheelbarrowMaker.activeMaking = {}; GardenWheelbarrowMaker.totalProducts = 0; GardenWheelbarrowMaker.dayTimer = 0
function GardenWheelbarrowMaker.init() GardenWheelbarrowMaker.ironStock=14; GardenWheelbarrowMaker.bronzeStock=12; GardenWheelbarrowMaker.woodStock=18; GardenWheelbarrowMaker.leatherStock=10; GardenWheelbarrowMaker.silverStock=8; GardenWheelbarrowMaker.goldStock=6; GardenWheelbarrowMaker.jewelStock=4; GardenWheelbarrowMaker.pearlStock=4; GardenWheelbarrowMaker.productStock={}; GardenWheelbarrowMaker.buildings={}; GardenWheelbarrowMaker.maker=nil; GardenWheelbarrowMaker.activeMaking={}; GardenWheelbarrowMaker.totalProducts=0; GardenWheelbarrowMaker.dayTimer=0; print("[GardenWheelbarrowMaker] Royal Garden Wheelbarrow Maker System initialized (6 products, 4 buildings)") end
function GardenWheelbarrowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenWheelbarrowMaker.maker={name=n or ("Vozičkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vozičkar najet: %s (spretnost: %d)",GardenWheelbarrowMaker.maker.name,s),"success") end; return true end
function GardenWheelbarrowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenWheelbarrowMaker.build(id) local ok,e=GardenWheelbarrowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenWheelbarrowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenWheelbarrowMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenWheelbarrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenWheelbarrowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenWheelbarrowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenWheelbarrowMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenWheelbarrowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenWheelbarrowMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenWheelbarrowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenWheelbarrowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenWheelbarrowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenWheelbarrowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenWheelbarrowMaker.buildings==0 then return false,"Potrebna vozičkarska delavnica" end; if not GardenWheelbarrowMaker.maker then return false,"Potreben vozičkar" end; return true end
function GardenWheelbarrowMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenWheelbarrowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenWheelbarrowMaker.ironStock=GardenWheelbarrowMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenWheelbarrowMaker.bronzeStock=GardenWheelbarrowMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenWheelbarrowMaker.woodStock=GardenWheelbarrowMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenWheelbarrowMaker.leatherStock=GardenWheelbarrowMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenWheelbarrowMaker.silverStock=GardenWheelbarrowMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenWheelbarrowMaker.goldStock=GardenWheelbarrowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenWheelbarrowMaker.jewelStock=GardenWheelbarrowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenWheelbarrowMaker.pearlStock=GardenWheelbarrowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenWheelbarrowMaker.maker then t=math.max(1,t-math.floor(GardenWheelbarrowMaker.maker.skill/13)) end; table.insert(GardenWheelbarrowMaker.activeMaking,{id="gardenwheelbarrow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenWheelbarrowMaker.completeMaking(m) local q=1.0+(GardenWheelbarrowMaker.getQualityBonus()/100); if GardenWheelbarrowMaker.maker then q=q+(GardenWheelbarrowMaker.maker.skill/140) end; q=math.min(2.5,q); GardenWheelbarrowMaker.productStock[m.productType]=(GardenWheelbarrowMaker.productStock[m.productType] or 0)+m.quantity; GardenWheelbarrowMaker.totalProducts=GardenWheelbarrowMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenWheelbarrowMaker.maker then GardenWheelbarrowMaker.maker.itemsMade=GardenWheelbarrowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenWheelbarrowMaker.maker.skill=math.min(100,GardenWheelbarrowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Voziček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenwheelbarrow.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenWheelbarrowMaker.update(dt) if not _G.state then return end; GardenWheelbarrowMaker.dayTimer=GardenWheelbarrowMaker.dayTimer+dt; if GardenWheelbarrowMaker.dayTimer>=30 then GardenWheelbarrowMaker.dayTimer=0; for i=#GardenWheelbarrowMaker.activeMaking,1,-1 do local m=GardenWheelbarrowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenWheelbarrowMaker.completeMaking(m); table.remove(GardenWheelbarrowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenWheelbarrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenWheelbarrowMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenWheelbarrowMaker.getStats() return {ironStock=GardenWheelbarrowMaker.ironStock,bronzeStock=GardenWheelbarrowMaker.bronzeStock,woodStock=GardenWheelbarrowMaker.woodStock,leatherStock=GardenWheelbarrowMaker.leatherStock,silverStock=GardenWheelbarrowMaker.silverStock,goldStock=GardenWheelbarrowMaker.goldStock,jewelStock=GardenWheelbarrowMaker.jewelStock,pearlStock=GardenWheelbarrowMaker.pearlStock,productStock=GardenWheelbarrowMaker.productStock,numBuildings=#GardenWheelbarrowMaker.buildings,hasMaker=GardenWheelbarrowMaker.maker~=nil,makerName=GardenWheelbarrowMaker.maker and GardenWheelbarrowMaker.maker.name or "—",makerSkill=GardenWheelbarrowMaker.maker and GardenWheelbarrowMaker.maker.skill or 0,activeMaking=#GardenWheelbarrowMaker.activeMaking,totalProducts=GardenWheelbarrowMaker.totalProducts} end
return GardenWheelbarrowMaker
